with cleaned as (select *, length(event_type) as event_type_length, trim(event_type) as clean_event_type from web_events where page is not distinct from '/search' and page in ('/product', '/search')), prev_events as (select *, lag(event_time) over (partition by event_type order by event_time, id) as prev_event_time from cleaned), flagged as (select *, case when prev_event_time is null or event_time > prev_event_time + interval 30 days then 1 else 0 end as new_group_flag from prev_events), islands as (select *, sum(new_group_flag) over (partition by event_type order by event_time, id rows between unbounded preceding and current row) as island_id from flagged) select session_id, date_trunc('week', event_time) as week_start, event_type, approx_percentile(new_group_flag, 0.5) as new_group_flag_p50, count(distinct session_id) as distinct_session_ids, max(event_type_length) filter (where event_type = 'purchase') as purchase_max_event_type_length, count(*) as event_count, min(prev_event_time) as first_prev_event_time from islands group by session_id, date_trunc('week', event_time), event_type;
